const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/);
    if (toks.length >= 2) {
        const n = parseInt(toks[0], 10), s = toks[1];
        let sum = 0;
        for (let i = 0; i < n; i++) sum += s.charCodeAt(i);
        console.log((sum / n).toFixed(2));
    }
}
main();

